import {europeanCountries} from './destinations.js';
const policies={DE:{percent:10,note:'독일은 좋은 서비스를 받았을 때 보통 10% 정도 팁을 내요.',url:'https://www.berlin.de/en/tourism/travel-information/1758234-2862820-tipping.en.html'},PT:{percent:5,note:'포르투갈은 좋은 서비스를 받았을 때 보통 5~10% 정도 팁을 내요.',url:'https://cdn.visitportugal.com/en//sobre-portugal/info-util'},IT:{percent:10,note:'이탈리아는 서비스에 만족하면 보통 10% 정도 팁을 내요. 의무는 아니에요.',url:'https://www.italia.it/en/italy/practical-information/money-payments-and-tipping-in-italy'},GB:{percent:12.5,note:'영국은 서비스료가 없고 서비스에 만족하면 보통 10~15% 팁을 내요.',url:'https://www.visitbritain.com/en/plan-your-trip/useful-information'},AT:{percent:10,note:'오스트리아는 좋은 서비스를 받았을 때 보통 5~10% 정도 팁을 내요.',url:'https://www.wien.info/fr/hotels-organisation/foire-aux-questions-346340'},FR:{percent:0,note:'프랑스는 추가 팁이 자율적이라 예상 금액에 따로 더하지 않아요.',url:'https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/pourboire'}};
export function tipCountry(restaurant,destination){if(europeanCountries.some(c=>c.code===restaurant?.countryCode))return restaurant.countryCode;const address=restaurant?.address||'';const found=europeanCountries.find(c=>address.includes(c.country)&&c.country.length>1);if(found)return found.code;if(/osteria la solita zuppa/i.test(restaurant?.name||''))return 'IT';return destination?.code;}
export function tipPolicy(code){return policies[code]||{percent:0,note:(europeanCountries.find(c=>c.code===code)?.country||'이 지역')+'의 팁 관행은 확인 중이라 자동으로 더하지 않아요.',unknown:true};}
export function cartEstimate(items,cart,percent=0){let subtotal=0,unknown=false;for(const i of items){const q=cart[i.id]||0;if(!q)continue;if(!Number.isFinite(i.price))unknown=true;else subtotal+=Math.round(i.price*100)*q;}const tip=Math.round(subtotal*percent/100);return {subtotal:subtotal/100,tip:tip/100,total:(subtotal+tip)/100,unknown};}
